const ART={"duke": "data:image/webp;base64,", "assassin": "data:image/webp;base64,", "captain": "data:image/webp;base64,", "ambassador": "data:image/webp;base64,", "contessa": "data:image/webp;base64,"};
// Original procedural score and effects. No third-party recordings.
let audioCtx=null,audioGain=null,musicClock=null,musicBeat=0;
let audioMuted=localStorage.getItem('coup-audio-muted')==='true';
let audioVolume=Number(localStorage.getItem('coup-audio-volume')??0.18);
function tone(freq,dur=0.2,type='sine',amp=0.18,delay=0,end=freq){if(!audioCtx||audioMuted)return;let t=audioCtx.currentTime+delay,o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(Math.max(20,end),t+dur);g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(0.0001,amp),t+0.02);g.gain.exponentialRampToValueAtTime(0.0001,t+dur);o.connect(g);g.connect(audioGain);o.start(t);o.stop(t+dur+0.04);}
function musicPulse(){if(document.hidden||audioMuted||!audioCtx)return;const bass=[55,55,51.91,55,49,49,51.91,58.27][Math.floor(musicBeat/4)%8];tone(bass,2.2,'sine',0.13);if(musicBeat%4===0){tone(bass*2,3,'triangle',0.035);tone(bass*1.4983,3,'sine',0.045,0.12);}if(musicBeat%2===0)tone(110,0.12,'triangle',0.06,0,45);musicBeat++;}
async function unlockAudio(){if(!audioCtx){audioCtx=new(window.AudioContext||window.webkitAudioContext)();audioGain=audioCtx.createGain();audioGain.gain.value=audioMuted?0:audioVolume*3*(window.coupVoiceDucked?0.2:1);audioGain.connect(audioCtx.destination);musicClock=setInterval(musicPulse,900);musicPulse();}if(audioCtx.state==='suspended')await audioCtx.resume();}
/* Outcome sounds: a brass fanfare for the winner, a sad trombone for whoever gets knocked out. */
function brass(freq,start,dur,{amp=.16,vib=0,bend=0,bright=2600,wah=false}={}){if(!audioCtx||audioMuted)return;const t=audioCtx.currentTime+start,o=audioCtx.createOscillator(),o2=audioCtx.createOscillator(),f=audioCtx.createBiquadFilter(),g=audioCtx.createGain();o.type='sawtooth';o2.type='square';o2.detune.value=7;o.frequency.setValueAtTime(freq,t);o2.frequency.setValueAtTime(freq,t);if(bend){o.frequency.linearRampToValueAtTime(freq*bend,t+dur);o2.frequency.linearRampToValueAtTime(freq*bend,t+dur);}
 if(vib){const l=audioCtx.createOscillator(),lg=audioCtx.createGain();l.frequency.value=vib;lg.gain.setValueAtTime(0,t);lg.gain.linearRampToValueAtTime(freq*.035,t+dur*.4);l.connect(lg);lg.connect(o.frequency);lg.connect(o2.frequency);l.start(t);l.stop(t+dur+.05);}
 f.type='lowpass';f.Q.value=wah?7:1.2;if(wah){f.frequency.setValueAtTime(350,t);f.frequency.linearRampToValueAtTime(1500,t+Math.min(.18,dur*.4));f.frequency.linearRampToValueAtTime(420,t+dur);}else{f.frequency.setValueAtTime(bright*.45,t);f.frequency.linearRampToValueAtTime(bright,t+.06);f.frequency.linearRampToValueAtTime(bright*.6,t+dur);}
 g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(amp,t+.035);g.gain.setValueAtTime(amp,t+dur*.75);g.gain.exponentialRampToValueAtTime(.0001,t+dur);
 o.connect(f);o2.connect(f);f.connect(g);g.connect(audioGain);o.start(t);o2.start(t);o.stop(t+dur+.05);o2.stop(t+dur+.05);}
function drum(start,freq=110,amp=.35){if(!audioCtx||audioMuted)return;const t=audioCtx.currentTime+start,o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(freq*.45,t+.35);g.gain.setValueAtTime(amp,t);g.gain.exponentialRampToValueAtTime(.0001,t+.45);o.connect(g);g.connect(audioGain);o.start(t);o.stop(t+.5);}
function victorySound(){unlockAudio();const C=523.25,E=659.25,G=783.99,C6=1046.5;
 // da-da-da DAAA, da-DAAAA
 [[G/2,0,.13],[G/2,.15,.13],[G/2,.3,.13],[C,.45,.55],[G/2*1.2,1.02,.18],[E,1.22,.2],[C6/2*1.5,1.44,1.3]].forEach(([f,s,d])=>brass(f,s,d,{amp:.15,vib:d>.5?5.5:0}));
 [[C,1.44],[E,1.44],[G,1.44]].forEach(([f,s])=>brass(f,s,1.3,{amp:.07,vib:5}));
 drum(.45,120,.4);drum(1.02,100,.25);drum(1.44,130,.45);drum(1.6,95,.25);
 [C6,1318.5,1568,2093].forEach((f,i)=>tone(f,.35,'triangle',.06,1.55+i*.09));[2093,2637,3136].forEach((f,i)=>tone(f,.5,'sine',.035,2.05+i*.07));}
function defeatSound(){unlockAudio();// wah, wah, wah, waaaaah
 [[293.66,0,.42],[277.18,.5,.42],[261.63,1.0,.42]].forEach(([f,s,d])=>brass(f/2,s,d,{amp:.2,bright:1100,wah:true,bend:.985}));
 brass(246.94/2,1.5,1.5,{amp:.21,bright:1000,wah:true,vib:6.5,bend:.94});tone(55,1.6,'sine',.12,1.5,41);}
function roundOverSound(){[392,329.63,261.63].forEach((f,i)=>tone(f,.6,'triangle',.1,i*.14));}
function soundFor(events){if(!audioCtx||audioMuted)return;let e=events.join(' ');if(e.includes('wins.')){const mine=state?.players.find(p=>p.id===seat?.id);if(state?.winner&&state.winner===seat?.id)victorySound();else if(mine&&!mine.spectator&&e.includes(mine.name+' lost '))defeatSound();else roundOverSound();return;}if(e.includes('removed')||e.includes('lost ')&&state?.players.some(p=>!p.cards.some(c=>!c.revealed)&&e.includes(p.name+' lost '))){const mine=state?.players.find(p=>p.id===seat?.id);if(mine&&!mine.spectator&&!mine.cards.some(c=>!c.revealed)&&(e.includes(mine.name+' lost ')||e.includes(mine.name+' was removed'))){defeatSound();return;}tone(90,1.2,'sine',.22,0,28);tone(135,1,'triangle',.08,.1,40);return;}if(e.includes('lost ')){tone(180,.65,'triangle',.2,0,42);return;}if(e.includes('challenges')){tone(440,.28,'sawtooth',.05);tone(466,.25,'sine',.17,.1);return;}if(e.includes('blocks')){tone(82,.18,'square',.08);tone(61,.3,'triangle',.2,.08);return;}if(e.includes('stole')){tone(330,.12,'triangle',.2);tone(220,.25,'triangle',.18,.12);return;}if(e.includes('proved')){tone(392,.18,'sine',.25);tone(523,.25,'sine',.2,.15);return;}if(e.includes('chose')||e.includes('exchanged')){tone(620,.1,'sine',.15);tone(880,.14,'sine',.14,.08);}}
function audioControl(){let header=document.querySelector('.top');if(!header)return;let box=document.createElement('div');box.className='audio-control';box.innerHTML='<button id="audio-mute" aria-label="Mute music and effects"></button><input id="audio-volume" type="range" min="0" max="0.5" step="0.01" aria-label="Music and sound volume">';header.append(box);const update=()=>{if(audioGain)audioGain.gain.setTargetAtTime(audioMuted?0:audioVolume*3*(window.coupVoiceDucked?0.2:1),audioCtx.currentTime,.03);box.querySelector('button').innerHTML=audioMuted?'<svg class="vc-i" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9h4l5-4v14l-5-4H4zM17 9l5 6M22 9l-5 6"/></svg>':'<svg class="vc-i" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9h4l5-4v14l-5-4H4zM16.5 8.5a5 5 0 0 1 0 7M19 6a8.5 8.5 0 0 1 0 12"/></svg>';box.querySelector('button').title=audioMuted?'Sound off':'Sound on';box.querySelector('button').setAttribute('aria-pressed',String(!audioMuted));box.querySelector('input').value=audioVolume;};update();box.querySelector('button').onclick=()=>{audioMuted=!audioMuted;localStorage.setItem('coup-audio-muted',audioMuted);unlockAudio();update();};box.querySelector('input').oninput=e=>{audioVolume=Number(e.target.value);localStorage.setItem('coup-audio-volume',audioVolume);unlockAudio();update();};document.addEventListener('pointerdown',unlockAudio,{once:true});document.addEventListener('keydown',unlockAudio,{once:true});document.addEventListener('visibilitychange',()=>{if(document.hidden)audioCtx?.suspend();else if(audioCtx&&!audioMuted)audioCtx.resume();});}
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defs={income:['Income','+1','','Take 1 coin. Cannot be blocked or challenged.'],aid:['Foreign aid','+2','Duke can block','Take 2 coins. Any other player may claim Duke to block.'],tax:['Duke: take 3','+3','','Take 3 coins.'],exchange:['Ambassador: exchange','Draw 2','','Draw 2 cards, keep your remaining influence count and return 2.'],steal:['Captain: steal 2','Up to 2','','Only the target may block with Captain or Ambassador.'],assassinate:['Assassinate','Pay 3','Claim Assassin','Target loses influence. Only target may block with Contessa.'],coup:['Coup','Pay 7','Cannot be blocked','Target loses influence. Mandatory at 10+ coins.']};
let openPlayer=null;let historyOpen=false;let serverOffset=0;let seat=null,state=null,version=0,busy=false,polling=false,error='',targetAction=null,selected=new Set();const codeFromURL=location.pathname.match(/^\/room\/([A-Fa-f0-9]{6})\/?$/)?.[1]?.toUpperCase();
try{seat=JSON.parse(localStorage.getItem('coup-seat-'+codeFromURL));}catch{}
function notify(text){$('#notice').textContent=text;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#notice').textContent='',6000);}
async function request(body){const options={headers:{'Content-Type':'application/json',...(seat?{Authorization:'Bearer '+seat.token}:{})}};if(body){options.method='POST';options.body=JSON.stringify(body);}const r=await fetch('/api/game'+(!body?'?code='+seat.code:''),options);const d=await r.json();if(d.state?.spectators?.length)d.state.players.push(...d.state.spectators);if(d.serverNow)serverOffset=d.serverNow-Date.now();if(!r.ok)throw Object.assign(new Error(d.error||'Connection failed.'),{status:r.status});return d;}
async function enter(type){const name=$('#name').value.trim(),code=$('#code')?.value.trim().toUpperCase();busy=true;$('#enter-error').textContent='';try{const d=await request({type,name,code});seat={token:d.token,id:d.id,code:d.code};localStorage.setItem('coup-seat-'+d.code,JSON.stringify(seat));state=d.state;version=d.version;history.replaceState(null,'','/room/'+d.code);render();}catch(e){$('#enter-error').textContent=e.message;}finally{busy=false;}}
function playerName(p){const can=seat.id===state.host&&p.id!==seat.id&&!p.removed;return can?`<button class="player-name" data-player-menu="${p.id}" aria-expanded="${openPlayer===p.id}">${esc(p.name)}</button>`:`<b class="player-name-text">${esc(p.name)}</b>`;}
function dmBadge(p){if(p.id===seat.id||p.removed)return '';const n=window.CoupChat?.unread(p.id)||0;return `<button class="seat-dm ${n?'has-unread':''}" data-seat-dm="${p.id}" aria-label="Message ${esc(p.name)}${n?', '+n+' unread':''}">✉${n?` <span>${n}</span>`:''}</button>`;}
function updateSeatDM(){document.querySelectorAll('[data-seat-dm]').forEach(b=>{const n=window.CoupChat?.unread(b.dataset.seatDm)||0;b.classList.toggle('has-unread',!!n);b.innerHTML='✉'+(n?' <span>'+n+'</span>':'');const p=state?.players.find(p=>p.id===b.dataset.seatDm);b.setAttribute('aria-label','Message '+(p?.name||'player')+(n?', '+n+' unread':''));b.onclick=()=>window.CoupChat?.openThread(b.dataset.seatDm);});}
window.addEventListener('coup-dm-unread',updateSeatDM);
