const ico=(n,cls='')=>`<svg class="vc-i ${cls}" viewBox="0 0 24 24" aria-hidden="true" focusable="false">${ICON[n]||''}</svg>`;
const ROLE={Duke:{i:'crown',tip:'Tax +3 · blocks Foreign aid'},Assassin:{i:'dagger',tip:'Assassinate · pay 3'},Captain:{i:'anchor',tip:'Steal 2 · blocks Steal'},Ambassador:{i:'swap',tip:'Exchange · blocks Steal'},Contessa:{i:'rose',tip:'Blocks Assassinate'}};
const ACTS={income:{label:'Income',i:'coin',badge:'+1'},aid:{label:'Aid',i:'coins',badge:'+2'},tax:{label:'Tax',i:'crown',badge:'+3',role:'Duke'},exchange:{label:'Exchange',i:'swap',badge:'⇄',role:'Ambassador'},steal:{label:'Steal',i:'anchor',badge:'+2',role:'Captain'},assassinate:{label:'Assassinate',i:'dagger',cost:3,role:'Assassin'},coup:{label:'Coup',i:'bolt',cost:7}};
