const me=()=>state.players.find(p=>p.id===seat.id), byId=id=>state?.players.find(p=>p.id===id), pname=id=>esc(byId(id)?.name||'Player'), living=p=>p.cards.some(c=>!c.revealed);
const seatedPlayers=()=>state.players.filter(p=>!p.spectator&&!p.removed);
