const nick=p=>p?.nickname||p?.username||'';
// back of the welcome fan cards: [heading, text] rows per role
const FAN_INFO={Duke:[['Action','<em>Tax</em> · take 3 coins'],['Blocks','Foreign aid']],Assassin:[['Action','<em>Assassinate</em> · pay 3 coins, a player loses a card'],['Blocked by','Contessa']],Captain:[['Action','<em>Steal</em> · take 2 coins from a player'],['Blocks','Stealing']],Ambassador:[['Action','<em>Exchange</em> · draw 2, keep the best, return 2'],['Blocks','Stealing']],Contessa:[['Action','None, she defends'],['Blocks','Assassination']]};
