async function loadAccount(){try{const r=await fetch('/api/auth',{credentials:'same-origin'}),d=await r.json();if(r.ok){account.profile=d.profile;account.leaders=d.leaders||[];account.googleClientId=d.googleClientId||null;}}catch{}account.loaded=true;accountChip();if(!state)render();if($('#vc-account')?.open)renderAccount();}
