/* ── choreography: compare the previous and next state, then schedule motion on an overlay ── */
const layer=document.createElement('div');layer.id='vc-fx';layer.setAttribute('aria-hidden','true');document.body.append(layer);
function anchor(sel){const el=document.querySelector(sel);if(!el)return null;const r=el.getBoundingClientRect();if(!r.width&&!r.height)return null;return {x:r.left+r.width/2,y:r.top+r.height/2,w:r.width,h:r.height};}
function center(){return anchor('#vc-play')||{x:innerWidth/2,y:innerHeight/2};}
function seatA(id,part='cards'){return anchor(`[data-seat="${id}"] .vc-${part}`)||anchor(`[data-seat="${id}"]`)||center();}
function fly(html,from,to,{dur=650,rot=0,s0=.55,s1=1,flip=false,flipDur,arc=0,fade='',cls='',easing=SPRING,hold=0}={}){
 from=typeof from==='function'?from():from;to=typeof to==='function'?to():to;if(!from||!to)return;
 const el=document.createElement('div');el.className='vc-fly '+cls;el.innerHTML=html;el.style.left=from.x+'px';el.style.top=from.y+'px';layer.append(el);
 const dx=to.x-from.x,dy=to.y-from.y,T=(x,y,s,r)=>`translate(-50%,-50%) translate(${x}px,${y}px) scale(${s}) rotate(${r}deg)`;
 const kf=arc?[{transform:T(0,0,s0,rot),opacity:fade==='in'?0:1},{transform:T(dx/2,dy/2-arc,(s0+s1)/2,rot/2),opacity:1,offset:.5},{transform:T(dx,dy,s1,0),opacity:fade==='out'?0:1}]:[{transform:T(0,0,s0,rot),opacity:fade==='in'?0:1},{transform:T(dx,dy,s1,0),opacity:fade==='out'?0:1}];
 const a=el.animate(kf,{duration:dur,easing:arc?'cubic-bezier(.3,.7,.4,1)':easing,fill:'forwards'});
 if(flip){const inner=el.querySelector('.vc-flip');inner?.animate([{transform:'rotateY(180deg)'},{transform:'rotateY(0deg)'}],{duration:flipDur||dur*.8,easing:'cubic-bezier(.45,.05,.3,1)',fill:'both',delay:flipDur?dur*.1:dur*.15});}
 a.onfinish=()=>{if(hold)setTimeout(()=>el.remove(),hold);else el.remove();};return el;}
function pop(html,at,{dur=800,cls=''}={}){const p=typeof at==='function'?at():at;if(!p)return;const el=document.createElement('div');el.className='vc-fly '+cls;el.innerHTML=html;el.style.left=p.x+'px';el.style.top=p.y+'px';layer.append(el);
 const dy=cls.includes('is-rise')?-70:cls.includes('is-sink')?50:0;el.animate([{transform:'translate(-50%,-50%) scale(.6)',opacity:0},{transform:'translate(-50%,-50%) scale(1.06)',opacity:1,offset:.3},{transform:`translate(-50%,calc(-50% + ${dy*.6}px)) scale(1)`,opacity:1,offset:.75},{transform:`translate(-50%,calc(-50% + ${dy}px)) scale(.96)`,opacity:0}],{duration:dur,easing:'ease-out',fill:'forwards'}).onfinish=()=>el.remove();}
function confetti(at){const p=at();if(!p)return;for(let i=0;i<26;i++){const el=document.createElement('i');el.className='vc-confetti';el.style.left=p.x+'px';el.style.top=p.y+'px';el.style.setProperty('--h',(i*47)%360);layer.append(el);const a=Math.random()*Math.PI*2,r=90+Math.random()*120;el.animate([{transform:'translate(-50%,-50%) rotate(0)',opacity:1},{transform:`translate(calc(-50% + ${Math.cos(a)*r}px),calc(-50% + ${Math.sin(a)*r+60}px)) rotate(${Math.random()*540}deg)`,opacity:0}],{duration:780,easing:'cubic-bezier(.2,.8,.3,1)',fill:'forwards'}).onfinish=()=>el.remove();}}
const backHTML=size=>`<div class="vc-card vc-${size} is-back"><div class="vc-flip"><div class="vc-front"></div><div class="vc-back"><span>${ico('crown')}</span></div></div></div>`;
const faceHTML=(role,size='m',extra='')=>card({id:'fly',role,revealed:false},{size,extra});
const coinHTML='<i class="vc-coinchip"></i>';
function coins(n,from,to,at){for(let k=0;k<Math.min(Math.abs(n),7);k++)at(k*70,()=>fly(coinHTML,from,to,{dur:560,arc:46,s0:.9,s1:.9}));}
function overlapFresh(a,b){for(let k=Math.min(a.length,b.length);k>=0;k--){let ok=true;for(let i=0;i<k;i++)if(a[a.length-k+i]!==b[i]){ok=false;break;}if(ok)return b.slice(k);}return b;}

function choreograph(prev,next,fresh){
 if(RM.matches||document.hidden||!fresh.length&&prev.phase?.type===next.phase?.type)return false;
 if(fresh.length>16)return false;
 const now=performance.now();let t=Math.max(now+60,fxEnd);const P=next.players,find=id=>P.find(p=>p.id===id),old=id=>prev.players.find(p=>p.id===id);
 const at=(off,fn)=>{const when=t+off;setTimeout(fn,Math.max(0,when-performance.now()));return when;};
 const named=(text,sep=' ')=>[...P].sort((a,b)=>b.name.length-a.name.length).find(p=>text.startsWith(p.name+sep)||text.startsWith(p.name+"'"));
 const acc=new Map(),add=(id,n)=>acc.set(id,(acc.get(id)||0)+n);
 const prevRevealed=new Set(prev.players.flatMap(p=>p.cards.filter(c=>c.revealed).map(c=>c.id))),used=new Set();
 let ctx={...(prev.action||{})},tid=prev.round!==next.round?0:(prev.turnNumber||0),last=null,coinsDone=false;
 const residual=()=>{if(coinsDone)return;coinsDone=true;let any=false;for(const p of P){const o=old(p.id);if(!o)continue;const r=p.coins-o.coins-(acc.get(p.id)||0);if(!r)continue;any=true;if(r>0)coins(r,()=>anchor('#vc-bank'),()=>seatA(p.id,'purse'),at);else coins(r,()=>seatA(p.id,'purse'),()=>anchor('#vc-bank'),at);fxMark('purse:'+p.id,'fx-bump',t+520,600);}if(any)t+=620;};
 for(const line of fresh){let m;const p=named(line);const sound=()=>at(0,()=>soundFor([line]));
  if(m=line.match(/^Round (\d+) started/)){tid=0;sound();const ps=P.filter(x=>!x.spectator&&x.cards.length);ps.forEach((x,k)=>{x.cards.forEach((c,j)=>{const d=(k*2+j)*80;at(d,()=>fly(backHTML('s'),()=>anchor('#vc-deck'),()=>seatA(x.id),{dur:520,rot:-20,s0:.8,s1:1}));});fxMark('dealt:'+x.id,'fx-dealt',t+k*160+420,500);coins(x.coins,()=>anchor('#vc-bank'),()=>seatA(x.id,'purse'),(o,fn)=>at(ps.length*160+300+o+k*60,fn));add(x.id,x.coins);});t+=ps.length*160+700;last='round';continue;}
  if(m=line.match(/ chose (\w+)/)){tid++;const kind=m[1],a=ACTS[kind],tg=[...P].sort((x,y)=>y.name.length-x.name.length).find(x=>line.endsWith(' against '+x.name+'.'));ctx={actor:p?.id,kind,target:tg?.id};sound();
   const html=a?.role?faceHTML(a.role,'m','is-claim'):tokenCard(kind);
   at(0,()=>fly(html,()=>seatA(ctx.actor),()=>anchor('#vc-play'),{dur:720,rot:-14,s0:.45,s1:1,flip:true,cls:'is-played'}));
   fxMark('play:'+tid,'fx-land',t+700,400);
   if(tg)fxMark('seat:'+tg.id+':target','fx-targeted',t+520,700);
   if(a?.cost){coins(a.cost,()=>seatA(ctx.actor,'purse'),()=>anchor('#vc-bank'),(o,fn)=>at(160+o,fn));add(ctx.actor,-a.cost);fxMark('purse:'+ctx.actor,'fx-bump',t+150,600);}
   t+=760;last='chose';continue;}
  if(m=line.match(/ challenges (\w+)\./)){const claimant=ctx.blocker||ctx.actor;sound();
   fxMark('dim','fx-dim',t,1500);fxMark('seat:'+p?.id+':spot','fx-spot-red',t,1500);fxMark('seat:'+claimant+':spot','fx-spot',t,1500);
   at(260,()=>fly(`<span class="vc-sword">${ico('swords')}</span>`,()=>seatA(p?.id,'cards'),()=>anchor('#vc-play'),{dur:520,s0:.6,s1:1.4,fade:'out',rot:-30}));
   t+=820;last='challenge';continue;}
  if(m=line.match(/ proved (\w+),/)){const role=m[1],cl=p?.id;sound();
   fxMark('dim','fx-dim',t-200,1600);fxMark('seat:'+cl+':spot','fx-spot',t-200,1600);
   at(0,()=>fly(faceHTML(role,'m','is-proved'),()=>seatA(cl),()=>({...center(),y:center().y-8}),{dur:780,s0:.5,s1:1.18,flip:true,flipDur:700,easing:'cubic-bezier(.25,.8,.3,1)',hold:300}));
   at(1080,()=>fly(faceHTML(role,'m'),()=>({...center(),y:center().y-8}),()=>anchor('#vc-deck'),{dur:460,s0:1.18,s1:.35,fade:'out',easing:'cubic-bezier(.5,0,.7,.4)'}));
   fxMark('deck','fx-shuffle',t+1500,500);
   at(1650,()=>fly(backHTML('s'),()=>anchor('#vc-deck'),()=>seatA(cl),{dur:520,s0:1,s1:1}));
   if(cl===seat.id){const o=old(cl),n=find(cl);n?.cards.forEach(c=>{const oc=o?.cards.find(x=>x.id===c.id);if(oc&&oc.role!==c.role&&!c.revealed)fxMark('card:'+c.id,'fx-new',t+2100,700);});}
   t+=2100;last='proved';continue;}
  if(m=line.match(/ concedes the (\w+) /)){sound();fxMark('dim','fx-dim',t-200,900);at(0,()=>pop(`<span class="vc-bigstamp is-bad">${ico('x')}</span>`,()=>anchor('#vc-play'),{dur:760}));t+=560;last='concede';continue;}
  if(m=line.match(/ blocks, claiming (\w+)\./)){ctx.blocker=p?.id;ctx.blockRole=m[1];sound();
   at(0,()=>fly(faceHTML(m[1],'m','is-claim is-block'),()=>seatA(ctx.blocker),()=>{const c=center();return {x:c.x+34,y:c.y+6};},{dur:700,rot:18,s0:.45,s1:1,flip:true}));
   fxMark('block:'+tid,'fx-land',t+680,400);t+=740;last='block';continue;}
  if(m=line.match(/ lost (\w+)\./)){const x=find(p?.id),role=m[1];sound();
   const c=x?.cards.find(c=>c.revealed&&c.role===role&&!prevRevealed.has(c.id)&&!used.has(c.id));if(c)used.add(c.id);
   const kind=last==='proved'?'failedChallenge':last==='concede'?'conceded':last===null?prev.phase?.reason?.kind:(['coup','assassinate'].includes(ctx.kind)&&x?.id===ctx.target?ctx.kind:'');
   const dramatic=['coup','assassinate'].includes(kind);
   if(dramatic){at(0,()=>fly(`<span class="vc-strike kind-${kind}">${ico(kind==='coup'?'bolt':'dagger')}</span>`,()=>seatA(ctx.actor),()=>seatA(x.id),{dur:440,s0:.6,s1:1.3,fade:'out',easing:'cubic-bezier(.5,0,.75,0)'}));fxMark('seat:'+x.id+':hit','fx-hit',t+420,500);}
   if(c)fxMark('card:'+c.id,dramatic?'fx-burn':'fx-reveal',t+(dramatic?400:0),dramatic?800:700);
   const eliminated=x&&!living(x)&&old(x.id)&&living(old(x.id));
   if(eliminated){const base=t+(dramatic?1250:750);fxMark('seat:'+x.id+':elim','fx-elim',base,800);x.cards.filter(k=>k.id!==c?.id).forEach((k,i)=>fxMark('card:'+k.id,'fx-flipover',base+120+i*160,600));fxMark('seat:'+x.id+':aura','fx-aura-loss',base,1700);at(dramatic?1250:750,()=>pop(`<span class="vc-aura is-loss">−1000 aura</span>`,()=>seatA(x.id),{dur:1500,cls:'is-sink'}));}
   t+=(dramatic?1250:760)+(eliminated?500:0);last='lost';continue;}
  if(m=line.match(/ stole (\d+) coin/)){const n=+m[1],tg=whoIn(line,P,' from ');sound();if(n){coins(n,()=>seatA(tg.id,'purse'),()=>seatA(p.id,'purse'),at);add(p.id,n);add(tg.id,-n);fxMark('purse:'+p.id,'fx-bump',t+560,600);fxMark('purse:'+tg.id,'fx-drain',t,500);}else at(0,()=>pop(`<span class="vc-bigstamp">0</span>`,()=>seatA(tg.id,'purse'),{dur:600}));t+=n?720:420;last='steal';continue;}
  if(/ exchanged with the court/.test(line)){sound();for(let k=0;k<2;k++)at(k*90,()=>fly(backHTML('s'),()=>seatA(p?.id),()=>anchor('#vc-deck'),{dur:500,s0:1,s1:.9}));fxMark('deck','fx-shuffle',t+560,500);t+=640;last='exchange';continue;}
  if(/^The action was blocked/.test(line)){fxMark('play:'+tid,'fx-blocked',t,600);t+=420;last='blocked';continue;}
  if(/^Turn resolved/.test(line)){residual();last='resolved';continue;}
  if(/ wins\.$/.test(line)){residual();sound();fxMark('win','fx-win',t,800);if(next.winner){fxMark('seat:'+next.winner+':aura','fx-aura-win',t,1900);at(250,()=>pop(`<span class="vc-aura is-win">+1000 aura</span>`,()=>seatA(next.winner),{dur:1600,cls:'is-rise'}));}at(120,()=>confetti(()=>anchor('#vc-play')));t+=800;last='win';continue;}
  if(/removed by the host/.test(line)){sound();if(p)fxMark('seat:'+p.id+':elim','fx-elim',t,800);t+=300;last='removed';continue;}
  sound();}
 residual();
 if(next.phase?.type==='exchange'&&prev.phase?.type!=='exchange'){const x=next.phase.player;for(let k=0;k<2;k++)at(k*90,()=>fly(backHTML('s'),()=>anchor('#vc-deck'),()=>seatA(x),{dur:520,s0:.9,s1:1}));if(x===seat.id)next.phase.cards?.forEach((c,i)=>fxMark('card:'+c.id,'fx-pop',t+300+i*70,600));t+=560;}
 if(next.status==='playing'&&next.phase?.type==='turn'&&next.players[next.turn]?.id===seat.id&&(prev.phase?.type!=='turn'||prev.turn!==next.turn||prev.round!==next.round))at(0,()=>pop(`<div class="vc-banner">${ico('crown')}<span>Your move</span></div>`,()=>anchor('.vc-stage')||center(),{dur:800}));
 fxEnd=t;return true;}

/* ── state intake (same requests and polling as before) ── */
function absorb(d){const prev=state,next=d.state;let fresh=[];
 if(prev)fresh=prev.round!==next.round?next.log:overlapFresh(prev.log||[],next.log||[]);
 const nextRound=next.readyCheck?.id&&next.readyCheck.id!==prev?.readyCheck?.id;
 const oldPrivate=(prev?.privateNotices||[]).map(x=>x.text),newPrivate=(next.privateNotices||[]).filter(x=>!oldPrivate.includes(x.text));
 if(next.status==='lobby'){const ids=next.players.map(p=>p.id);if(lobbySeen)ids.filter(id=>!lobbySeen.has(id)).forEach(id=>fxMark('slot:'+id,'fx-pop',performance.now(),700));lobbySeen=new Set(ids);}
 let animated=false;if(prev){state=next;animated=choreograph(prev,next,fresh);}if(prev?.status==='playing'&&next.status==='finished'&&next.players.find(p=>p.id===seat?.id)?.ranked)setTimeout(loadAccount,1800);
 state=next;version=d.version;render();
 if(prev&&!animated)soundFor(fresh);
 if(nextRound&&!next.players.find(p=>p.id===seat?.id)?.ready){notify('Next round · tap Ready');[440,660].forEach((f,i)=>tone(f,.3,'sine',.2,i*.2));}
 if(prev&&newPrivate.length)notify('Time ran out · auto move');{const before=(prev?.kickVotes?.[seat?.id]||[]).length,now=(next.kickVotes?.[seat?.id]||[]),voters=next.players.filter(x=>!x.removed&&!x.spectator&&x.id!==seat?.id).length;if(prev&&now.length>before)notify(`${pname(now.at(-1))} voted to kick you (${now.length}/${voters})`);}}
async function sync(){if(!seat||polling||busy)return;polling=true;try{const d=await request();if(version!==d.version||!state){targetAction=null;selected.clear();absorb(d);}if($('#connection'))$('#connection').textContent='Connected';$('#connection')?.classList.remove('is-off');}catch(e){if(e.status===401){state=null;seat=null;$('#app').innerHTML=`<section class="vc-gone">${ico('skull','vc-gone-i')}<h1>Seat closed</h1><a class="vc-btn gold big" href="/">${ico('home')}Home</a></section>`;return;}if($('#connection')){$('#connection').textContent='Reconnecting…';$('#connection').classList.add('is-off');}}finally{polling=false;}}
/* Moves race when several players answer the same window. On a version conflict, refresh;
   if the same decision is still waiting for this player, resend instead of asking them to click again. */
function decisionKey(s){if(!s)return '';const ph=s.phase,mine=ph?.eligible?ph.eligible.includes(seat.id)&&!ph.passed.includes(seat.id):ph?.player===seat.id;return [s.status,s.round,s.turn,s.turnNumber,ph?.type,ph?.player||'',mine,!!s.readyCheck].join('|');}
async function send(move){if(busy)return;busy=true;render();const key=decisionKey(state);try{let d=null;for(let attempt=0;attempt<4;attempt++){try{d=await request({code:seat.code,version,move});break;}catch(e){if(e.status!==409)throw e;const fresh=await request();absorb(fresh);if(decisionKey(state)!==key)return;}}if(!d)throw new Error('The table is busy. Try again.');if(d.voiceWarning)notify(d.voiceWarning);targetAction=null;selected.clear();busy=false;absorb(d);}catch(e){notify(e.message);busy=false;await sync();}finally{busy=false;render();}}


/* ── How to play: a six-step visual guide built from the game's own cards and icons ── */
let rulesStep=0;
const RULE_STEPS=[['crown','Goal'],['play','Your turn'],['users','Characters'],['swords','Bluff'],['shield','Blocking'],['hourglass','Online']];
const rCard=(role,size='m')=>card({id:'rule-'+role,role,revealed:false},{size});
const rBack=(size='m')=>`<div class="vc-card vc-${size} is-back"><div class="vc-flip"><div class="vc-front"></div><div class="vc-back"><span>${ico('crown')}</span></div></div></div>`;
const rCoins=n=>`<span class="vr-coins">${'<i class="vc-coinchip"></i>'.repeat(n)}</span>`;
function rulesPanel(i){
 if(i===0)return `<h2>Be the last one standing</h2>
 <div class="vr-hero"><div class="vr-hand">${rBack()}${rBack()}</div><span class="vr-eq">+</span>${rCoins(2)}</div>
 <ul class="vr-points">
  <li><b>${ico('crown')}</b><span>Everyone gets <strong>2 secret cards</strong> and <strong>2 coins</strong>. Your cards are your lives.</span></li>
  <li><b>${ico('skull')}</b><span>Lose a fight → turn <strong>one card face-up</strong>. Both face-up → <strong>you're out</strong>.</span></li>
  <li><b>${ico('trophy')}</b><span>The <strong>last player with a hidden card wins</strong>.</span></li>
  <li><b>${ico('users')}</b><span>Only 2 players? Whoever starts gets just 1 coin.</span></li></ul>`;
 if(i===1)return `<h2>On your turn, do one thing</h2><p class="vr-lead">Some actions need a character. You can say you have it even if you don't. That's the bluff.</p>
 <div class="vr-acts">${Object.entries(ACTS).map(([k,a])=>{const blk=BLOCKERS[k]||[];return `<div class="vr-act ${a.role?'role-'+a.role.toLowerCase():'act-'+k}"><span class="vr-act-i">${ico(a.i)}</span><b>${a.label}</b><span class="vr-act-fx">${({income:'Take 1 coin',aid:'Take 2 coins',tax:'Take 3 coins',exchange:'Swap cards with the deck',steal:'Take 2 coins from a player',assassinate:'Pay 3 · a player loses a card',coup:'Pay 7 · a player loses a card'})[k]}</span><span class="vr-tag">${a.role?`${roleSig(a.role)}Say you're ${a.role}`:`${ico('check')}Anyone can`}</span><span class="vr-tag is-block">${k==='coup'?`${ico('x')}Can't be stopped`:k==='income'?`${ico('x')}Can't be stopped`:blk.length?`${ico('shield')}Blocked by ${blk.map(r=>roleSig(r)).join('')}`:`${ico('swords')}Can be challenged`}</span></div>`;}).join('')}</div>
 <div class="vr-note is-hot">${ico('bolt')}<span>Got <strong>10 or more coins</strong>? You <strong>must Coup</strong>.</span></div>`;
 if(i===2)return `<h2>The five characters</h2><p class="vr-lead">There are 3 copies of each in the deck. Claim any of them, whether you hold it or not.</p>
 <div class="vr-roles">${[['Duke','Take 3 coins','Foreign aid'],['Assassin','Pay 3, a player loses a card',null],['Captain','Steal 2 coins','Stealing'],['Ambassador','Swap cards with the deck','Stealing'],['Contessa',null,'Assassination']].map(([r,does,blocks])=>`<div class="vr-role role-${r.toLowerCase()}">${rCard(r)}<div><b>${r}</b>${does?`<span>${ico('play')}${does}</span>`:''}${blocks?`<span class="is-block">${ico('shield')}Blocks ${blocks}</span>`:''}</div></div>`).join('')}</div>`;
 if(i===3)return `<h2>Call the bluff</h2><p class="vr-lead">When someone claims a character, <strong>anyone</strong> can challenge them.</p>
 <div class="vr-flow"><div class="vr-step">${rCard('Duke','s')}<span>"I'm the Duke, I take 3"</span></div><span class="vr-arrow">${ico('arrow')}</span><div class="vr-step is-hot">${ico('swords','vr-big')}<span>"Liar!" Challenge</span></div></div>
 <div class="vr-outcomes"><div class="vr-out is-ok"><b>${ico('check')}They really had it</b><span>They show the card, shuffle it back and draw a new one.</span><span><strong>The challenger loses a card.</strong> The action happens.</span></div>
 <div class="vr-out is-bad"><b>${ico('x')}They were bluffing</b><span><strong>The liar loses a card.</strong></span><span>The action is cancelled and any coins paid come back.</span></div></div>
 <div class="vr-note">${ico('swords')}<span>Only challenge when you're fairly sure. Getting it wrong costs <strong>you</strong> a card.</span></div>`;
 if(i===4)return `<h2>Stop them with a block</h2><p class="vr-lead">A block is also a claim, so it can be challenged too.</p>
 <div class="vr-blocks">${[['aid','Duke','Anyone can block']].concat([['steal','Captain','Only the target'],['steal','Ambassador','Only the target'],['assassinate','Contessa','Only the target']]).map(([k,r,who])=>`<div class="vr-block"><span class="vr-act-i">${ico(ACTS[k].i)}</span><b>${ACTS[k].label}</b><span class="vr-arrow">${ico('shield')}</span>${rCard(r,'s')}<span class="vr-who">${r}<small>${who}</small></span></div>`).join('')}</div>
 <div class="vr-note">${ico('dagger')}<span>A blocked assassination <strong>still costs the 3 coins</strong>. A Coup can't be blocked.</span></div>
 <div class="vr-note is-hot">${ico('skull')}<span>Watch out: you can lose <strong>both cards</strong> in one turn if you wrongly challenge an Assassin, or fake a Contessa and get caught.</span></div>`;
 return `<h2>Playing online</h2><p class="vr-lead">Timers keep the game moving. If time runs out, the game picks for you.</p>
 <div class="vr-timers"><div>${ico('crown')}<b>45s</b><span>Your turn</span><small>Too slow → Income (or a random Coup at 10+ coins)</small></div><div>${ico('swords')}<b>20s</b><span>Challenge / block / reveal</span><small>Too slow → you accept, auto-prove if you can, or lose a random card</small></div><div>${ico('swap')}<b>30s</b><span>Exchange</span><small>Too slow → you keep your cards</small></div></div>
 <ul class="vr-points">
  <li><b>${ico('swords')}</b><span>The <strong>first</strong> challenge or block counts. Be quick.</span></li>
  <li><b>${ico('copy')}</b><span>Share the room code or invite link. Refreshing keeps your seat; rooms close after 24 hours without a move.</span></li>
  <li><b>${ico('trophy')}</b><span>Sign in to earn points: 10 for each player who finishes below you, +20 for the win.</span></li></ul>
 <p class="vr-small">Base Coup rules, no Reformation. <a href="https://www.buffalolib.org/sites/default/files/gaming-unplugged/inst/Coup%20Instructions.pdf" target="_blank" rel="noopener">Printed rulebook</a> · Fan-made, original art.</p>`;}
function renderRules(){const d=$('#rules');if(!d)return;const i=rulesStep,last=RULE_STEPS.length-1;
 d.classList.add('vc-rules');
 d.innerHTML=`<header class="vr-head"><span class="vc-eyebrow">${ico('q')}How to play</span><button class="vc-iconbtn" id="vr-close" aria-label="Close">${ico('x')}</button></header>
 <nav class="vr-tabs" role="tablist">${RULE_STEPS.map(([icon,l],k)=>`<button role="tab" aria-selected="${k===i}" data-rule-step="${k}" class="${k<i?'is-done':''}"><span>${k+1}</span>${l}</button>`).join('')}</nav>
 <section class="vr-panel" role="tabpanel" aria-live="polite">${rulesPanel(i)}</section>
 <footer class="vr-foot"><button class="vc-btn ghost" id="vr-prev" ${i?'':'disabled'}>${ico('arrow','vr-back')}Back</button><span class="vr-dots">${RULE_STEPS.map((_,k)=>`<i class="${k===i?'is-on':''}"></i>`).join('')}</span>${i<last?`<button class="vc-btn gold" id="vr-next">Next${ico('arrow')}</button>`:`<button class="vc-btn gold" id="vr-done">${ico('check')}Let's play</button>`}</footer>`;
 const go=k=>{rulesStep=Math.max(0,Math.min(last,k));renderRules();d.querySelector('.vr-panel')?.scrollIntoView({block:'nearest'});};
 d.querySelector('#vr-close').onclick=()=>d.close();d.querySelector('#vr-done')?.addEventListener('click',()=>{d.close();rulesStep=0;});
 d.querySelector('#vr-prev').onclick=()=>go(i-1);d.querySelector('#vr-next')?.addEventListener('click',()=>go(i+1));
 d.querySelectorAll('[data-rule-step]').forEach(b=>b.onclick=()=>go(+b.dataset.ruleStep));
 d.onkeydown=e=>{if(e.key==='ArrowRight')go(i+1);if(e.key==='ArrowLeft')go(i-1);};}
function openRules(){const d=$('#rules');renderRules();if(!d.open)d.showModal();if(!d.dataset.bound){d.dataset.bound='1';d.addEventListener('click',e=>{if(e.target===d)d.close();});}}
$('#rules-open').innerHTML=ico('q');$('#rules-open').setAttribute('aria-label','How to play');$('#rules-open').title='How to play';
$('#rules-open').onclick=()=>openRules();$('#rules-close').onclick=()=>$('#rules').close();$('#rule-actions').innerHTML=Object.entries(defs).map(([k,d])=>`<div class="rule-row"><b>${d[0]} <span>${d[1]}</span></b><p>${d[3]}</p></div>`).join('');audioControl();loadAccount();render();if(seat)sync();setInterval(()=>{if(!document.hidden)sync();},2000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync();});

window.addEventListener("coup-voice-duck",e=>{window.coupVoiceDucked=e.detail;if(audioGain)audioGain.gain.setTargetAtTime(audioMuted?0:audioVolume*3*(e.detail?0.2:1),audioCtx.currentTime,.15);});
